# CELL 1
# ============================== CONFIGURATION ==============================
# Everything you would normally want to change lives in this one cell.

SCOPE = "pilot"          # "smoke" | "pilot" | "full"
#   smoke : ~20 min. 24 cases, 2 epochs, 2 models. Wiring proof only.
#   pilot : a few hours. All cases, fold 0, 3 models, short schedule.
#   full  : the run matrix. Needs several sessions; resumes from the ledger.

TIME_BUDGET_HOURS = 8.0  # training stops cleanly before the Kaggle ceiling
SEED = 42
RUN_UNIT_TESTS = True    # ~10 s; catches a broken environment before training
DUAL_GPU = True          # use both T4s as two independent workers when present
RESUME_FROM = None       # e.g. "/kaggle/input/<previous-notebook-output>" to continue

# Evaluation cost controls (volume inferences are the expensive part).
N_LOCKED_TEST = None     # None = all locked-test cases
N_SUBSET_CASES = 24      # cases used for the exhaustive 15-subset / Shapley table
N_CORRUPTION_CASES = 16  # cases used for the 6 x 3 corruption grid

# If the MSD dataset is not attached, fail loudly rather than quietly inventing
# data. Set this to True only to rehearse the pipeline on synthetic volumes.
ALLOW_SYNTHETIC_FALLBACK = False

PRESETS = {
    "smoke": dict(limit_cases=24, models=["qmmf_net", "hemis25d"], folds=[0],
                  seeds=[SEED], max_epochs=2, steps_per_epoch=20, batch_size=2,
                  crop=[96, 96], widths=[16, 32, 64], max_val_cases=6,
                  bootstrap=1000, n_subset_cases=4, n_corruption_cases=4,
                  n_locked=8),
    "pilot": dict(limit_cases=None,
                  models=["qmmf_net", "hemis25d", "unet25d"], folds=[0],
                  seeds=[SEED], max_epochs=40, steps_per_epoch=150, batch_size=4,
                  crop=[192, 192], widths=[24, 48, 96, 160], max_val_cases=16,
                  bootstrap=10000, n_subset_cases=N_SUBSET_CASES,
                  n_corruption_cases=N_CORRUPTION_CASES, n_locked=N_LOCKED_TEST),
    "full": dict(limit_cases=None,
                 models=["qmmf_net", "hemis25d", "unet25d", "unet2d", "segresnet3d"],
                 folds=[0, 1, 2, 3], seeds=[SEED], max_epochs=120,
                 steps_per_epoch=250, batch_size=4, crop=[192, 192],
                 widths=[24, 48, 96, 160], max_val_cases=24, bootstrap=10000,
                 n_subset_cases=N_SUBSET_CASES,
                 n_corruption_cases=N_CORRUPTION_CASES, n_locked=N_LOCKED_TEST),
}
assert SCOPE in PRESETS, SCOPE
P = PRESETS[SCOPE]
REPORTABLE = (SCOPE == "full")

print(f"SCOPE={SCOPE}  reportable={REPORTABLE}")
print(f"models={P['models']} folds={P['folds']} epochs={P['max_epochs']}")
if not REPORTABLE:
    print("\nThis scope produces pipeline evidence, not study results. Every")
    print("output file will carry scope='" + SCOPE + "' and not_reportable=True.")

