_payload = "".join(_PAYLOAD_B64.split())
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(_payload)), mode="r:gz") as tf:
    tf.extractall(REPO)
sys.path.insert(0, str(REPO / "src"))
print("repo unpacked at", REPO)
