# Dependencies. Kaggle images already carry torch, numpy, scipy, pandas,
# scikit-learn, matplotlib and usually nibabel.
def ensure(pkg, module=None):
    try:
        __import__(module or pkg)
        return "present"
    except ImportError:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], check=False)
        try:
            __import__(module or pkg)
            return "installed"
        except ImportError:
            return "UNAVAILABLE"

for pkg, mod in [("nibabel", "nibabel"), ("monai", "monai"),
                 ("statsmodels", "statsmodels"), ("PyYAML", "yaml")]:
    print(f"  {pkg:12s} {ensure(pkg, mod)}")
# monai is only needed for the B4 SegResNet comparator; its absence is reported
# rather than silently dropping the baseline.

