# CELL 6
# Cell 05 - resolve the dataset root. Fail loudly when it is missing or ambiguous.
import os
from pathlib import Path
from qmmf.paths import DatasetRootError, KAGGLE_SLUG, resolve_primary_root

SYNTHETIC = False

# Your actual attached datasets don't sit at the hardcoded candidate paths
# resolve_primary_root() checks — they're nested under /kaggle/input/datasets/<owner>/<slug>.
MY_CANDIDATES = [
    "/kaggle/input/datasets/thisisrick25/medical-segmentation-decathlon-brain-tumour",
    "/kaggle/input/datasets/naishagajkandh/msd-brain-tumour",
]

def find_msd_root(base_dirs):
    """Walk each base dir looking for the MSD Task01 layout (dataset.json + imagesTr)."""
    for base in base_dirs:
        base = Path(base)
        if not base.exists():
            continue
        # exact match
        if (base / "dataset.json").exists() and (base / "imagesTr").exists():
            return base
        # search one/two levels deeper for a nested copy of the folder
        for candidate in base.rglob("dataset.json"):
            folder = candidate.parent
            if (folder / "imagesTr").exists():
                return folder
    return None

try:
    ROOT = resolve_primary_root()
    print("MSD Task01 root:", ROOT)
except DatasetRootError as exc:
    print("DATASET NOT RESOLVED via default candidates:", exc)
    print("Trying your attached dataset paths directly...")

    found_root = find_msd_root(MY_CANDIDATES)

    if found_root is not None:
        ROOT = found_root
        print("MSD Task01 root (found via fallback search):", ROOT)
    elif not ALLOW_SYNTHETIC_FALLBACK:
        # Show what's actually under /kaggle/input/datasets to help debug
        for base in MY_CANDIDATES:
            p = Path(base)
            print(f"\nContents of {base} (exists={p.exists()}):")
            if p.exists():
                for item in sorted(p.rglob("*"))[:30]:
                    print(" ", item)
        raise SystemExit(
            f"Could not locate dataset.json/imagesTr under either attached dataset. "
            "Check the printed listing above for the real nested path, then add it "
            "to MY_CANDIDATES, or set ALLOW_SYNTHETIC_FALLBACK=True to rehearse the pipeline."
        )
    else:
        SYNTHETIC = True
        sys.path.insert(0, str(REPO / "scripts"))
        from smoke_test import make_synthetic_cohort
        ROOT = make_synthetic_cohort(WORK / "synthetic_data", n=16)
        print("USING SYNTHETIC DATA:", ROOT)
        print("Nothing produced below refers to real brain MRI.")

from qmmf.manifest import load_dataset_json
dataset_json = load_dataset_json(ROOT)
print("dataset.json modality block:", (dataset_json or {}).get("modality"))
print("dataset.json labels block:  ", (dataset_json or {}).get("labels"))

# CELL 7
# Cell 06 - integrity audit, label-scheme verification and gate G0.
# MSD Task01 (1=edema, 2=non-enhancing, 3=enhancing) and BraTS-legacy
# (1=necrotic, 2=edema, 4=enhancing) map the same integers to different
# regions, so the scheme is read and verified, never assumed.
from qmmf.manifest import build_manifest, discover_cases

t0 = time.time()
manifest, report = build_manifest(ROOT, limit=P["limit_cases"], progress=True)
manifest.to_csv(ARTIFACTS / "manifest.csv", index=False)
write_json(ARTIFACTS / "dataset_fingerprint.json", report)

print(f"\ncases                {report['n_cases']}   ({time.time()-t0:.0f}s)")
print(f"label scheme         {report['label_scheme']} {report['label_scheme_mapping']}")
print(f"failed cases         {report['n_failed_cases']}")
print(f"exact duplicates     {len(report['duplicates']['exact_duplicate_groups'])}")
print(f"spacing uniform      {report['geometry'].get('spacing_is_uniform')}")
print(f"manifest hash        {report['manifest_hash']}")
print(f"G0 gate_pass         {report['gate_pass']}")

if report["n_failed_cases"]:
    print("\nfailing cases:", json.dumps(report["failed_cases"][:5], indent=2)[:1200])
assert report["gate_pass"], "G0 failed: fix the data problems above before training."

if not SYNTHETIC and report["n_cases"] != 484 and P["limit_cases"] is None:
    print(f"\nNOTE: the plan expects 484 labelled cases; this mirror has "
          f"{report['n_cases']}. Record the deviation in the data section.")

# CELL 8
# Cell 07 - stratified split lock: locked test, four development folds.
from qmmf.labels import LabelScheme
from qmmf.splits import Splits, build_splits, validate_splits

splits = build_splits(manifest, seed=SEED)
SPLIT_HASH = splits.save(ARTIFACTS / "adult_splits.json")
validate_splits(splits)
assert Splits.load(ARTIFACTS / "adult_splits.json").split_hash == SPLIT_HASH
assert not set(splits.locked_test) & set(splits.development)

SCHEME = LabelScheme(name=report["label_scheme"], **report["label_scheme_mapping"])
print("scheme       ", SCHEME.name, SCHEME.component_labels())
print("WT =", sorted(SCHEME.wt_labels()), "| TC =", sorted(SCHEME.tc_labels()),
      "| ET =", sorted(SCHEME.et_labels()))

print("locked test  ", len(splits.locked_test), "cases  (untouched until cell 15)")
print("development  ", len(splits.development), "cases")
for k, part in splits.folds.items():
    print(f"  fold {k}: train {len(part['train'])} / inner {len(part['inner_val'])} "
          f"/ outer {len(part['outer_val'])}")
print("split hash   ", SPLIT_HASH)

# CELL 9
# Cell 08 - build the preprocessed per-case cache (the slow, resumable step).
from qmmf.dataset import CaseCache

cache = CaseCache(CACHE_DIR, SCHEME)
cases = {c["case_id"]: c for c in discover_cases(ROOT)}
wanted = [c for c in manifest.case_id.astype(str)]

t0 = time.time(); built = 0
for i, cid in enumerate(wanted, 1):
    if cache.path(cid).exists():
        continue
    c = cases[cid]
    cache.build(cid, c["image_path"], c["label_path"])
    built += 1
    if built % 25 == 0:
        rate = (time.time() - t0) / built
        print(f"  cached {i}/{len(wanted)}  ({rate:.1f}s/case, "
              f"~{rate*(len(wanted)-i)/60:.0f} min left)", flush=True)

n_files = len(list(CACHE_DIR.glob("*.npz")))
size_gb = sum(p.stat().st_size for p in CACHE_DIR.glob("*.npz")) / 1024**3
print(f"cache: {n_files} files, {size_gb:.2f} GB, {built} built this session "
      f"({time.time()-t0:.0f}s)")

# CELL 10
# Cell 09 - the experiment configuration, frozen here for the whole session.
import ast
from qmmf.config import ExperimentConfig
from qmmf.quality import QualityNormalizer

BASE_YAML = REPO / "configs" / "base.yaml"
cfg = ExperimentConfig.load(BASE_YAML) if BASE_YAML.exists() else ExperimentConfig()
cfg = cfg.merged({
    "seed": SEED,
    "out_dir": str(WORK / "qmmf_runs"),
    "data.crop_size": P["crop"],
    "data.manifest_hash": report["manifest_hash"],
    "data.split_hash": SPLIT_HASH,
    "data.root": str(ROOT),
    "net.widths": P["widths"],
    "train.max_epochs": P["max_epochs"],
    "train.steps_per_epoch": P["steps_per_epoch"],
    "train.batch_size": P["batch_size"],
    "train.num_workers": 2 if os.cpu_count() and os.cpu_count() > 2 else 0,
    "train.amp": torch.cuda.is_available(),
    "train.seed": SEED,
    "evaluation.bootstrap_replicates": P["bootstrap"],
})
cfg.save(ARTIFACTS / "preprocessing_config.json")

def _spacing(row):
    z = row.zooms
    return tuple(z) if isinstance(z, (list, tuple)) else tuple(ast.literal_eval(str(z)))
spacing = {str(r.case_id): _spacing(r) for r in manifest.itertuples()}

# Quality normalisers are fitted on TRAINING cases only, per fold.
QNORM = {}
for f in splits.folds:
    p_art = ARTIFACTS / f"quality_norm_fold{f}.json"
    if p_art.exists():
        QNORM[f] = QualityNormalizer.from_dict(json.loads(p_art.read_text()))
    else:
        QNORM[f] = QualityNormalizer.fit(
            [cache.load(c)["quality_raw"] for c in splits.folds[f]["train"]])
        write_json(p_art, QNORM[f].to_dict())
    # scripts/run_worker.py looks for these beside the cache directory
    write_json(CACHE_DIR.parent / f"quality_norm_fold{f}.json", QNORM[f].to_dict())

print("config hash:", cfg.config_hash())
print("quality normalisers fitted for folds:", sorted(QNORM))
sample = cache.load(splits.development[0])
print("raw quality matrix [M, Q]:\n", np.round(sample["quality_raw"], 3))

# CELL 11
# Cell 10 - model registry, parameter budget, and the masking guarantees.
from qmmf.models import ABLATIONS, BASELINE_IDS, MODEL_REGISTRY, build_model, project_nested
from qmmf.utils import count_parameters

param_table = {}
for name in sorted(set(P["models"]) | {"qmmf_net"}):
    try:
        m = build_model(cfg.merged({"model": name}))
        param_table[name] = count_parameters(m)["total"] / 1e6
    except ImportError as exc:
        param_table[name] = f"unavailable ({exc})"
print(json.dumps(param_table, indent=2, default=str))

model = build_model(cfg)
params_m = count_parameters(model)["total"] / 1e6
print(f"\nQMMF-Net {params_m:.2f}M parameters (gate: < 8M) -> "
      f"{'PASS' if params_m < 8 else 'FAIL'}")

# An absent modality must be unable to change the output: inputs are zeroed,
# the softmax denominator excludes it, and the max branch uses a finite sentinel.
B, M, D, H, W, Q = 2, 4, cfg.data.context_slices, 64, 64, cfg.net.quality_dim
image = torch.randn(B, M, D, H, W); quality = torch.randn(B, M, Q)
avail = torch.tensor([[1., 1., 0., 1.], [0., 0., 1., 0.]])
image = image * avail[:, :, None, None, None]
model.eval()
with torch.no_grad():
    a = model(image, avail, quality)
    perturbed = image.clone(); perturbed[0, 2] = torch.randn_like(perturbed[0, 2]) * 50
    b = model(perturbed, avail, quality)
assert torch.allclose(a, b, atol=1e-5), "absent-modality leakage detected"
probs = project_nested(torch.sigmoid(a))
assert (probs[:, 2] <= probs[:, 1] + 1e-6).all() and (probs[:, 1] <= probs[:, 0] + 1e-6).all()
print("masking + nesting checks passed (50-sigma perturbation of an absent modality)")

# CELL 12
# Cell 11 - measured VRAM and throughput. GATE G1. No planning estimates here.
from qmmf.dataset import SliceDataset
from qmmf.trainer import check_resource_gates, speed_and_memory_pilot

PILOT_STEPS = 20 if SCOPE == "smoke" else 100
ds_pilot = SliceDataset(splits.folds["0"]["train"], cache, cfg.data,
                        quality_norm=QNORM["0"],
                        length=PILOT_STEPS * cfg.train.batch_size, seed=SEED)
ds_pilot.set_epoch(0, cfg.train.max_epochs)

efficiency = {}
for name in P["models"]:
    try:
        c = cfg.merged({"model": name})
        pilot = speed_and_memory_pilot(c, ds_pilot, steps=PILOT_STEPS, device=DEVICE)
        gates = check_resource_gates(pilot)
        efficiency[name] = {**pilot, **gates}
        print(f"{name:12s} {pilot['parameters_millions']:5.2f}M  "
              f"VRAM {pilot['peak_vram_gb']:5.2f} GB  "
              f"{pilot['steps_per_second']:5.2f} steps/s  "
              f"vram_pass={gates['vram_pass']}")
    except Exception as exc:
        efficiency[name] = {"error": repr(exc)}
        print(f"{name:12s} pilot failed: {exc!r}")

write_json(ARTIFACTS / "efficiency_benchmark.json", efficiency)
if torch.cuda.is_available() and "qmmf_net" in efficiency:
    assert efficiency["qmmf_net"].get("vram_pass"), \
        "G1 failed: reduce widths/crop or enable gradient checkpointing."

# CELL 13
# Cell 12 - queue the run matrix and train. Resumable, time-budgeted.
from qmmf.evaluate import validation_metrics
from qmmf.ledger import ExperimentQueue, Ledger
from qmmf.splits import training_cases
from qmmf.trainer import Trainer
from qmmf.worker import build_experiment_queue, launch_dual_gpu, run_worker, wait_for

QUEUE = ARTIFACTS / "experiment_queue.json"
LEDGER = ARTIFACTS / "experiment_ledger.csv"
BUDGET = TIME_BUDGET_HOURS * 3600

n_queued = build_experiment_queue(QUEUE, models=P["models"], folds=P["folds"],
                                  seeds=P["seeds"], base_cfg=cfg)
print("queued:", n_queued, "| queue state:", ExperimentQueue(QUEUE).summary())

def run_one(run_cfg, gpu):
    train_ids = training_cases(splits, run_cfg.fold, run_cfg.label_fraction)
    inner = splits.folds[str(run_cfg.fold)]["inner_val"]
    qn = QNORM[str(run_cfg.fold)]
    ds = SliceDataset(train_ids, cache, run_cfg.data, quality_norm=qn,
                      curriculum=run_cfg.train.modality_curriculum,
                      length=run_cfg.train.steps_per_epoch * run_cfg.train.batch_size,
                      seed=run_cfg.train.seed)

    def validate(m, epoch):
        return validation_metrics(m, inner, cache, run_cfg, spacing, device=DEVICE,
                                  max_cases=P["max_val_cases"])

    trainer = Trainer(run_cfg, ds, validate, device=DEVICE, run_dir=run_cfg.run_dir())
    state = trainer.fit(resume=True)
    last = state.history[-1] if state.history else {}
    return {
        "best_epoch": state.best_epoch, "best_score": state.best_score,
        "checkpoint": str(run_cfg.run_dir() / "best.pt"),
        "full_macro_dice": last.get("val_full_macro_dice", ""),
        "mean_subset_macro_dice": last.get("val_mean_subset_macro_dice", ""),
        "worst_subset_macro_dice": last.get("val_worst_subset_macro_dice", ""),
        "parameters": count_parameters(trainer.model)["total"],
    }

t0 = time.time()
if DUAL_GPU and N_GPU >= 2:
    # Two T4s are two devices, not one 32 GB device: two independent single-GPU
    # workers sharing a lock-protected queue and one ledger.
    procs = launch_dual_gpu(
        REPO / "scripts" / "run_worker.py", QUEUE, LEDGER,
        ["--base", str(ARTIFACTS / "preprocessing_config.json"),
         "--cache", str(CACHE_DIR),
         "--splits", str(ARTIFACTS / "adult_splits.json"),
         "--manifest", str(ARTIFACTS / "manifest.csv"),
         "--max-val-cases", str(P["max_val_cases"]),
         "--time-budget", str(BUDGET)])
    print("two workers launched; this cell blocks until they finish.")
    print("codes:", wait_for(procs, poll=60.0))
else:
    run_worker(gpu=0, queue_path=QUEUE, ledger_path=LEDGER, run_one=run_one,
               base_cfg=cfg, time_budget_seconds=BUDGET,
               src_root=REPO / "src")
print(f"training wall time: {(time.time()-t0)/3600:.2f} h")

ledger = Ledger(LEDGER).read()
if len(ledger):
    cols = [c for c in ["model", "fold", "seed", "status", "best_epoch",
                        "full_macro_dice", "parameters", "wall_seconds"]
            if c in ledger.columns]
    print(ledger[cols].to_string(index=False))
    print("\nqueue after run:", ExperimentQueue(QUEUE).summary())
    print("Failures and OOMs stay in the ledger as failed / resource_rejected "
          "rows; they are reported, not deleted.")
else:
    print("no runs recorded — check the worker output above")

# CELL 14
# Cell 13 - ARCHITECTURE LOCK (G4). Nothing below may change these choices.
lock = {
    "gate_id": "G4_architecture_lock",
    "protocol_version": cfg.protocol_version,
    "locked_at_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    "scope": SCOPE, "reportable": REPORTABLE,
    "config": cfg.to_dict(), "config_hash": cfg.config_hash(),
    "manifest_hash": report["manifest_hash"], "split_hash": SPLIT_HASH,
    "decision_threshold": 0.5,
    "threshold_source": "protocol default; no locked-test sweep",
    "post_processing": "hard nesting projection ET subset TC subset WT; no size filtering",
    "calibration": "region-wise temperature scaling fitted on development only",
    "non_inferiority_margin_pp": cfg.evaluation.non_inferiority_margin_pp,
    "primary_endpoint": "locked-test full-modality patient-level macro Dice (WT, TC, ET)",
}
write_json(ARTIFACTS / "model_lock.json", lock)
print(json.dumps({k: v for k, v in lock.items() if k != "config"}, indent=2))

# CELL 15
# Cell 14 - load the best checkpoint per model from the ledger.
MODELS = {}
if len(ledger):
    done = ledger[ledger.status == "completed"]
    for name in P["models"]:
        rows = done[done.model == name]
        if rows.empty:
            print(f"  {name}: no completed run")
            continue
        row = rows.sort_values("best_score", ascending=False).iloc[0]
        ck = torch.load(row.checkpoint, map_location=DEVICE, weights_only=False)
        m = build_model(cfg.merged({"model": name}))
        m.load_state_dict(ck["model"])
        MODELS[name] = m.to(DEVICE).eval()
        print(f"  {name}: fold {row.fold} seed {row.seed} "
              f"best_epoch {row.best_epoch} score {row.best_score}")
if not MODELS:
    raise RuntimeError("No completed runs to evaluate. Inspect the ledger above.")

# CELL 16
# Cell 15 - THE PRIMARY ENDPOINT: locked-test inference, full modality.
# This is the first time the locked test is touched.
from qmmf.evaluate import evaluate_cases
from qmmf.metrics import summarize

LOCKED = splits.locked_test[:P["n_locked"]] if P["n_locked"] else splits.locked_test
print(f"locked-test cases evaluated: {len(LOCKED)} of {len(splits.locked_test)}")

primary = {}
for name, m in MODELS.items():
    t0 = time.time()
    res = evaluate_cases(m, LOCKED, cache, cfg, spacing,
                         threshold=lock["decision_threshold"], device=DEVICE)
    primary[name] = res
    s = res["summary"]
    print(f"  {name:12s} macro={s['macro_dice']:.4f}  wt={s['dice_wt']:.4f}  "
          f"tc={s['dice_tc']:.4f}  et={s['dice_et']:.4f}  "
          f"empty-ET-refs={s['n_empty_reference_et']}  ({time.time()-t0:.0f}s)")
    pd.DataFrame([r.__dict__ for r in res["rows"]]).to_csv(
        RESULTS / f"locked_full_{name}.csv", index=False)

table = pd.DataFrame({k: v["summary"] for k, v in primary.items()}).T
table.to_csv(RESULTS / "table_locked_full_modality.csv")
print()
print(table[[c for c in table.columns if c.startswith(("dice", "macro", "hd95", "nsd"))]]
      .round(4).to_string())
print("\nMacro Dice excludes empty-reference regions, which are counted "
      "separately, so free 1.0s cannot inflate the headline.")

# CELL 17
# Cell 16 - exhaustive 15-subset table and EXACT Shapley attribution.
from qmmf.evaluate import evaluate_all_subsets
from qmmf.shapley import gate_shapley_alignment, patient_shapley_table
from qmmf.subsets import ALL_SUBSET_KEYS, subset_key

SUB_CASES = LOCKED[:P["n_subset_cases"]]
print(f"{len(ALL_SUBSET_KEYS)} subsets x {len(SUB_CASES)} patients "
      f"= {15*len(SUB_CASES)} volume inferences per model")

subset_results, shapley_tables = {}, {}
for name, m in MODELS.items():
    t0 = time.time()
    sub = evaluate_all_subsets(m, SUB_CASES, cache, cfg, spacing, device=DEVICE)
    subset_results[name] = sub
    write_json(RESULTS / f"subsets_{name}.json", sub["subset_summary"])
    shap = patient_shapley_table(sub["per_case"])
    shap.to_csv(RESULTS / f"shapley_{name}.csv", index=False)
    shapley_tables[name] = shap
    gap = float(shap.efficiency_gap.abs().max())
    assert gap < 1e-9, f"Shapley efficiency axiom violated for {name}: {gap}"
    print(f"  {name:12s} mean subset macro="
          f"{np.mean(list(sub['mean_over_subsets'].values())):.4f}  "
          f"worst={np.mean(list(sub['worst_subset'].values())):.4f}  "
          f"max|efficiency gap|={gap:.1e}  ({time.time()-t0:.0f}s)")
    print("      mean phi: " + ", ".join(
        f"{mm}={shap[mm].mean():+.4f}" for mm in cfg.data.modalities))

# Gate weights vs exact Shapley (QMMF-Net only; the other models have no gate).
alignment = {}
full_key = subset_key(tuple(cfg.data.modalities))
if "qmmf_net" in subset_results and subset_results["qmmf_net"]["gates"].get(SUB_CASES[0]):
    gate_rows = [{"case_id": c, **dict(zip(cfg.data.modalities,
                  np.asarray(subset_results["qmmf_net"]["gates"][c][full_key]).mean(0)))}
                 for c in SUB_CASES]
    alignment = gate_shapley_alignment(
        gate_rows, shapley_tables["qmmf_net"].to_dict("records"),
        modalities=cfg.data.modalities)
    write_json(RESULTS / "gate_shapley_alignment.json",
               {k: v for k, v in alignment.items() if not isinstance(v, list)})
    print(f"\ngate-Shapley: mean rho={alignment['mean_spearman']:+.3f}  "
          f"mean mismatch={alignment['mean_mismatch']:.3f}  n={alignment['n_cases']}")
    print("'Interpretable gates' stays an unclaimed hypothesis unless this "
          "alignment is strong AND stable across folds and regions.")

print("\nConvention: v(empty set) = 0. A negative Shapley value means an added "
      "sequence hurt that patient; it is a finding, not a bug to clip away.")

# CELL 18
# Cell 17 - calibration and whether the uncertainty is actually useful.
# Temperature is fitted on DEVELOPMENT cases only; the locked test never
# contributes to the fit. Voxels are subsampled with a fixed RNG because a
# full-resolution probability map per case does not fit in RAM.
from qmmf.calibration import (TemperatureScaler, calibration_report,
                              failure_detection_scores, failure_labels,
                              risk_coverage_curve, selective_performance)
from qmmf.inference import predict_volume

VOXELS_PER_CASE = 200_000
N_CAL_CASES = min(12, len(LOCKED))
DEV_CAL = splits.folds["0"]["inner_val"][:N_CAL_CASES]
rng = np.random.default_rng(SEED)

def logit(p, eps=1e-6):
    p = np.clip(np.asarray(p, dtype=np.float32), eps, 1 - eps)
    return np.log(p / (1 - p))

def sample_voxels(model, case_ids):
    """Return (logits, labels) as [3, N] arrays of subsampled voxels."""
    L, Y = [], []
    for cid in case_ids:
        out = predict_volume(model, cid, cache, cfg, device=DEVICE)
        pr = np.asarray(out["probs"]).reshape(3, -1)
        ref = np.asarray(out["reference"]).reshape(3, -1).astype(np.float32)
        k = min(VOXELS_PER_CASE, pr.shape[1])
        idx = rng.choice(pr.shape[1], size=k, replace=False)
        L.append(logit(pr[:, idx])); Y.append(ref[:, idx])
    return np.concatenate(L, axis=1), np.concatenate(Y, axis=1)

reliability = {}
for name, m in MODELS.items():
    t0 = time.time()
    dev_logits, dev_labels = sample_voxels(m, DEV_CAL)
    scaler = TemperatureScaler.fit(dev_logits, dev_labels)

    test_logits, test_labels = sample_voxels(m, LOCKED[:N_CAL_CASES])
    before = calibration_report(1 / (1 + np.exp(-test_logits.ravel())),
                                test_labels.ravel(), cfg.evaluation.calibration_bins)
    after = calibration_report(scaler.transform_probs(test_logits).ravel(),
                               test_labels.ravel(), cfg.evaluation.calibration_bins)

    scores = [primary[name]["per_case_macro"][c] for c in LOCKED]
    unc = [primary[name]["uncertainty"][c]["mean_entropy"] for c in LOCKED]
    fail = failure_labels(scores, 0.60)
    detect = failure_detection_scores(unc, fail)
    reliability[name] = {
        "temperatures": scaler.temperatures.tolist(),
        "n_calibration_cases_dev": len(DEV_CAL),
        "calibration_before": before, "calibration_after": after,
        "failure_detection": detect,
        "selective": selective_performance(scores, unc,
                                           cfg.evaluation.selective_coverages),
    }
    write_json(RESULTS / f"temperature_{name}.json", scaler.to_dict())
    print(f"  {name:12s} T={np.round(scaler.temperatures, 3).tolist()}  "
          f"ECE {before['ece']:.4f} -> {after['ece']:.4f}  "
          f"Brier {before['brier']:.4f} -> {after['brier']:.4f}  "
          f"({time.time()-t0:.0f}s)")
    print(f"      failure detection (Dice < 0.60): {detect}")
    print(f"      selective: {reliability[name]['selective']}")

write_json(RESULTS / "reliability.json", reliability)
print("\nAUROC is nan when no case falls on one side of the 0.60 threshold; "
      "that is reported as 'not evaluable', not as a passing result.")
print("Uncertainty has to be shown USEFUL (failure AUROC, monotone "
      "risk-coverage), not merely displayed as a heatmap.")

# CELL 19
# Cell 18 - the fixed corruption suite: 6 corruptions x 3 severities.
# Severities were fixed before any locked-test inference and are NOT drawn
# from the training augmentation distribution.
from qmmf.transforms import corruption_grid

grid = corruption_grid()
CORR_CASES = LOCKED[:P["n_corruption_cases"]]
print(f"{len(grid)} conditions x {len(CORR_CASES)} cases per model")

corruption_results = {}
for name, m in MODELS.items():
    rows = {}
    for spec in grid:
        res = evaluate_cases(m, CORR_CASES, cache, cfg, spacing,
                             corrupt={**spec, "seed": 1234}, device=DEVICE)
        rows[f"{spec['kind']}_s{spec['severity']}"] = res["summary"]["macro_dice"]
    corruption_results[name] = rows
    clean = float(np.mean([primary[name]["per_case_macro"][c] for c in CORR_CASES]))
    worst = min(rows, key=rows.get)
    print(f"  {name:12s} clean={clean:.4f}  mean_corrupted="
          f"{np.mean(list(rows.values())):.4f}  worst={worst} ({rows[worst]:.4f})")

write_json(RESULTS / "corruptions.json", corruption_results)
pd.DataFrame(corruption_results).round(4).to_csv(RESULTS / "table_corruptions.csv")

# CELL 20
# Cell 19 - paired patient-level statistics, Holm correction, non-inferiority.
from qmmf.stats import apply_holm, compare_paired, non_inferiority

comparisons, family, h1 = [], [], None
if "qmmf_net" in primary:
    for other in [m for m in primary if m != "qmmf_net"]:
        shared = sorted(set(primary["qmmf_net"]["per_case_macro"]) &
                        set(primary[other]["per_case_macro"]))
        a = [primary["qmmf_net"]["per_case_macro"][c] for c in shared]
        b = [primary[other]["per_case_macro"][c] for c in shared]
        family.append(compare_paired(a, b, name=f"qmmf_vs_{other}",
                                     n_boot=cfg.evaluation.bootstrap_replicates))
    comparisons = apply_holm(family)
    for r in comparisons:
        print(f"  {r.name:22s} diff={r.mean_difference:+.4f} "
              f"[{r.ci_low:+.4f}, {r.ci_high:+.4f}] p={r.p_value:.4f} "
              f"p_holm={r.p_holm:.4f} dz={r.effect_size:+.3f} n={r.n}")
    write_json(RESULTS / "paired_comparisons.json", [r.to_dict() for r in comparisons])

# H1: non-inferiority to the volumetric baseline, margin locked in advance.
ref_model = "segresnet3d" if "segresnet3d" in primary else (
    "unet25d" if "unet25d" in primary else None)
if ref_model and "qmmf_net" in primary:
    shared = sorted(set(primary["qmmf_net"]["per_case_macro"]) &
                    set(primary[ref_model]["per_case_macro"]))
    h1 = non_inferiority([primary["qmmf_net"]["per_case_macro"][c] for c in shared],
                         [primary[ref_model]["per_case_macro"][c] for c in shared],
                         margin=cfg.evaluation.non_inferiority_margin_pp / 100,
                         n_boot=cfg.evaluation.bootstrap_replicates)
    h1["comparator"] = ref_model
    write_json(RESULTS / "h1_non_inferiority.json", h1)
    print(f"\nH1 vs {ref_model}: non_inferior={h1['non_inferior']} "
          f"superior={h1['superior']} margin={h1['margin']}")
    if ref_model != "segresnet3d":
        print("NOTE: the pre-specified H1 comparator is B4 (segresnet3d). This "
              "is a substitute because B4 was not trained in this run.")

print("\nHolm correction is applied WITHIN a comparison family, never across "
      "all comparisons at once. Comparisons are patient-level and paired; "
      "a t-test across four fold means would be wrong.")

# CELL 21
# Cell 20 - figures generated from the immutable result files.
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

# F1: per-subset macro Dice heatmap (models x subsets).
if subset_results:
    keys = ALL_SUBSET_KEYS
    mat = np.array([[subset_results[n]["subset_summary"][k]["macro_dice"] for k in keys]
                    for n in subset_results])
    fig, ax = plt.subplots(figsize=(12, 1.1 * len(subset_results) + 2))
    im = ax.imshow(mat, aspect="auto", vmin=0, vmax=1, cmap="viridis")
    ax.set_xticks(range(len(keys))); ax.set_xticklabels(keys, rotation=90, fontsize=7)
    ax.set_yticks(range(len(subset_results))); ax.set_yticklabels(list(subset_results))
    for i in range(mat.shape[0]):
        for j in range(mat.shape[1]):
            ax.text(j, i, f"{mat[i,j]:.2f}", ha="center", va="center",
                    fontsize=6, color="w")
    fig.colorbar(im, label="macro Dice"); ax.set_title("All 15 modality subsets")
    fig.tight_layout(); fig.savefig(FIGURES / "fig_subset_heatmap.png", dpi=150)
    plt.close(fig)

# F2: per-patient Shapley distribution for QMMF-Net.
if "qmmf_net" in shapley_tables:
    s = shapley_tables["qmmf_net"]
    fig, ax = plt.subplots(figsize=(6, 4))
    ax.boxplot([s[m] for m in cfg.data.modalities])
    ax.set_xticklabels(list(cfg.data.modalities))
    ax.axhline(0, color="k", lw=0.8)
    ax.set_ylabel("exact Shapley value (macro Dice)")
    ax.set_title("Modality contribution, per patient")
    fig.tight_layout(); fig.savefig(FIGURES / "fig_shapley.png", dpi=150); plt.close(fig)

# F3: risk-coverage for each model.
fig, ax = plt.subplots(figsize=(6, 4))
for name in primary:
    sc = [primary[name]["per_case_macro"][c] for c in LOCKED]
    un = [primary[name]["uncertainty"][c]["mean_entropy"] for c in LOCKED]
    curve = risk_coverage_curve(sc, un)
    ax.plot(curve["coverage"], curve["risk"], marker=".", label=name)
ax.set_xlabel("coverage"); ax.set_ylabel("risk (1 - macro Dice on retained)")
ax.legend(); ax.set_title("Risk-coverage on the locked test")
fig.tight_layout(); fig.savefig(FIGURES / "fig_risk_coverage.png", dpi=150); plt.close(fig)

# F4: measured efficiency, not planning targets.
ok = {k: v for k, v in efficiency.items() if "parameters_millions" in v}
if ok:
    fig, ax = plt.subplots(figsize=(6, 4))
    for k, v in ok.items():
        y = primary[k]["summary"]["macro_dice"] if k in primary else np.nan
        ax.scatter(v["parameters_millions"], y, s=60)
        ax.annotate(k, (v["parameters_millions"], y), fontsize=8,
                    xytext=(4, 4), textcoords="offset points")
    ax.set_xlabel("parameters (M, measured)"); ax.set_ylabel("locked-test macro Dice")
    ax.set_title("Accuracy vs size (measured)")
    fig.tight_layout(); fig.savefig(FIGURES / "fig_efficiency.png", dpi=150); plt.close(fig)

print("figures written:")
for p in sorted(FIGURES.glob("*.png")):
    print("  ", p.name, f"{p.stat().st_size/1024:.0f} KB")
from IPython.display import Image, display
for p in sorted(FIGURES.glob("*.png")):
    display(Image(filename=str(p)))

# CELL 22
# Cell 21 - result card, claim discipline, and the reproducibility bundle.
import shutil
from qmmf.utils import code_hash

REJECTED_CLAIMS = [
    "State of the art - not permitted unless all relevant methods are fairly "
    "reproduced or a recognised benchmark verifies it.",
    "External clinical validation / clinical readiness / radiologist-level - "
    "not supported by this design.",
    "Quality-aware - not permitted without the A5 (no quality) and A17 "
    "(shuffled quality) controls, which this notebook did not run.",
    "Interpretable gates - not permitted without stable gate-Shapley alignment.",
]
LIMITATIONS = [
    "MSD Task01 derives from older adult BraTS cohorts; it is not a "
    "contemporary multicentre clinical sample.",
    "The model is 2.5D; volumetric context is approximated.",
    "No pediatric out-of-domain cohort was run here.",
    "Quality features are handcrafted and may miss real acquisition defects.",
    "No reader study, prospective trial or workflow evaluation.",
]
card = {
    "protocol_version": cfg.protocol_version,
    "scope": SCOPE, "reportable": REPORTABLE, "synthetic_data": SYNTHETIC,
    "config_hash": cfg.config_hash(), "split_hash": SPLIT_HASH,
    "manifest_hash": report["manifest_hash"],
    "n_cases": int(report["n_cases"]),
    "n_locked_test_evaluated": len(LOCKED),
    "models_trained": sorted(MODELS),
    "epochs_configured": cfg.train.max_epochs,
    "locked_test_summary": {k: v["summary"] for k, v in primary.items()},
    "shapley_mean": {n: {m: float(s[m].mean()) for m in cfg.data.modalities}
                     for n, s in shapley_tables.items()},
    "gate_shapley": {k: v for k, v in alignment.items() if not isinstance(v, list)},
    "non_inferiority": h1,
    "paired_comparisons": [r.to_dict() for r in comparisons],
    "rejected_claims": REJECTED_CLAIMS, "limitations": LIMITATIONS,
    "ablations_run": [], "pediatric_ood": "not run",
}
if not REPORTABLE:
    card["not_reportable"] = (
        f"scope='{SCOPE}': a shortened schedule on a subset of the run matrix. "
        "These numbers show the pipeline runs end to end and say nothing "
        "about segmentation quality. Do not put them in a manuscript."
    )
if SYNTHETIC:
    card["not_reportable"] = "SYNTHETIC DATA. No statement about real MRI."
write_json(RESULTS / "result_card.json", card)

bundle = ARTIFACTS / "reproducibility_bundle"; bundle.mkdir(exist_ok=True)
for name in ("dataset_fingerprint.json", "adult_splits.json", "model_lock.json",
             "efficiency_benchmark.json", "experiment_ledger.csv",
             "preprocessing_config.json", "environment.json", "manifest.csv"):
    if (ARTIFACTS / name).exists():
        shutil.copy2(ARTIFACTS / name, bundle / name)
for p in list(RESULTS.glob("*")) + list(FIGURES.glob("*.png")):
    if p.is_file():
        shutil.copy2(p, bundle / p.name)
write_json(bundle / "code_and_environment.json", {
    "code_hash": code_hash(REPO / "src"),
    "environment": environment_fingerprint(),
    "exported_at_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
})
shutil.make_archive(str(WORK / "qmmf_bundle"), "zip", bundle)

print(json.dumps({k: card[k] for k in
                  ("scope", "reportable", "n_cases", "models_trained",
                   "locked_test_summary")}, indent=2, default=str))
print("\nbundle:", WORK / "qmmf_bundle.zip")
for p in sorted(bundle.iterdir()):
    print(f"  {p.name:44s} {p.stat().st_size/1024:8.1f} KB")
if not REPORTABLE:
    print("\n" + card["not_reportable"])